5.3 &lt;a href=&#34;#3.%E6%9E%84%E9%80%A0%E5%87%BD%E6%95%B0(%E6%95%B0%E7%BB%84%E7%9B%B4%E6%8E%A5%E5%BB%BA%E5%A0%86)&#34;&gt;构造函数 (数组直接建堆)&lt;/a&gt;&lt;br /&gt;
5.4 &lt;a href=&#34;#4.%E5%90%91%E4%B8%8B%E8%B0%83%E6%95%B4%E7%AE%97%E6%B3%95&#34;&gt;向下调整算法&lt;/a&gt;&lt;br /&gt;
